mapper.select:
SELECT * FROM wallet_transaction

ORDER BY ${sortCol} ${sortDir}, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT w.user_id AS "userId", u.username AS "username", u.real_name AS "realName", u.phone AS "phone", u.status AS "userStatus", w.balance AS "balance", w.total_recharge AS "totalRecharge", w.total_spent AS "totalSpent", w.total_earned AS "totalEarned", w.status AS "status", w.updated_at AS "updatedAt", (SELECT string_agg(r.role_code, ',') FROM sys_user_role ur JOIN sys_role r ON r.id = ur.role_id WHERE ur.user_id = u.id) AS "roles" FROM wallet_account w JOIN sys_user u ON u.id = w.user_id
AND (u.username ILIKE '%' || #{keyword} || '%' OR u.real_name ILIKE '%' || #{keyword} || '%' OR u.phone ILIKE '%' || #{keyword} || '%')
ORDER BY ${sortCol} ${sortDir}, w.user_id DESC LIMIT #{limit} OFFSET #{offset}
